#define SAMPLES_W 30
#define MAXSTEPS 15
#define time iTime
#define v2Resolution iResolution
#define PI 3.141592

float sph(vec4 p, float r) { return length(p)-r; }
float cyl2(vec2 p, float r) { return length(p)-r; }
float box(vec4 p, float s) { vec4 ap = abs(p); return min(length(max(vec4(0),ap-s)), max(max(ap.x,ap.y),max(ap.z,ap.w))-s); }
float box2(vec2 p, float s) { vec2 ap = abs(p); return min(length(max(vec2(0),ap-s)),max(ap.x, ap.y)-s); }

vec4 rep(vec4 p, vec4 s) {
    return (fract(p/s-0.5)-0.5)*s;
}

vec4 rid(vec4 p, vec4 s) {
    return floor(p/s-0.5);
}

mat2 rot(float a) {
    float ca=cos(a);
    float sa=sin(a);
    return mat2(ca,sa,-sa,ca);
}

float map(vec4 p, float size, int mode, vec2 cell) {
    float spd = 0.6;
    float cell_factor = cell.x + cell.y * 2.0 + 1.0;
    float base_speed = time * spd;
    float d;

    if (mode == 0) {
        // Classic tesseract with twist
        p.yz *= rot(base_speed * 0.05 * cell_factor);
        p.xw *= rot(base_speed * cell_factor);
        p.yw *= rot(base_speed * 0.2 * cell_factor);
        p.xw *= rot(base_speed * 0.7 * sin(cell_factor));
        p.zw *= rot(base_speed * 0.3 * cos(cell_factor));

        d = box(p, 1.0);
        float c = box2(p.xz, size);
        c = min(c, box2(p.xy, size - 0.5*cell_factor));
        c = min(c, box2(p.yz, size));
        c = min(c, box2(p.xw, size));
        c = min(c, box2(p.yw, size));
        c = min(c, box2(p.zw, size));
        d = max(d, -c);
    }
    else if (mode == 1) {
        // Nested rotating tesseracts
        p.yz *= rot(base_speed * 0.1 * cell_factor);
        p.xw *= rot(-base_speed * cos(cell_factor));
        p.yw *= rot(base_speed * 0.3 * sin(cell_factor));

        float outer = box(p, 1.2);
        vec4 p2 = p;
        p2.xz *= rot(base_speed * 0.5 * cell_factor);
        p2.yw *= rot(base_speed * 0.7 * cell_factor);
        float inner = box(p2, 0.7);

        float c = box2(p.xz, size * 1.1);
        c = min(c, box2(p.xy, size * 1.1));
        c = min(c, box2(p.yz, size * 1.1));
        c = min(c, box2(p.xw, size * 1.1 + cell_factor));
        float c2 = box2(p2.xz, size * 0.6);
        c2 = min(c2, box2(p2.xy, size * 0.6));
        c2 = min(c2, box2(p2.yz, size * 0.6));
        c2 = min(c2, box2(p2.xw, size * 0.6));

        outer = max(outer, -c);
        inner = max(inner, -c2);
        d = min(outer, inner);
    }
    else if (mode == 2) {
        // Fractal tesseract
        p.xz *= rot(time * 0.2);
        p.yw *= rot(time * 0.3);
        p.zw *= rot(time * 0.4);

        float scale = 1.0;
        d = box(p, 1.0);

        for(int i = 0; i < 2; i++) {
            vec4 p2 = p;
            p2.xz *= rot(time * float(i+1) * 0.2);
            p2.yw *= rot(time * float(i+1) * 0.3);
            scale *= 0.5;
            p2 *= 2.0;
            float d2 = box(p2, 1.0) * scale;
            d = min(d, d2);
        }

        float c = box2(p.xz, size);
        c = min(c, box2(p.xy, size));
        c = min(c, box2(p.yz, size - abs(cell_factor)));
        c = min(c, box2(p.xw, size));
        d = max(d, -c);
    }
    else {
        // Twisted dual tesseract
        p.xz *= rot(base_speed * 0.3 * cell_factor + p.w * 0.5);
        p.yw *= rot(base_speed * 0.4 * sin(cell_factor) + p.x * 0.5);
        p.zw *= rot(base_speed * 0.5 * cos(cell_factor) + p.y * 0.5);

        float d1 = box(p, 1.0);
        vec4 p2 = p;
        p2.xz *= rot(PI * 0.25);
        p2.yw *= rot(PI * 0.25);
        float d2 = box(p2, 1.0);

        float c1 = box2(p.xz, size);
        c1 = min(c1, box2(p.xy, size));
        c1 = min(c1, box2(p.yz, size));
        float c2 = box2(p2.xz, size);
        c2 = min(c2, box2(p2.xy, size));
        c2 = min(c2, box2(p2.yz, size));

        d1 = max(d1, -c1);
        d2 = max(d2, -c2);
        d = min(d1, d2);
    }

    return d;
}

vec3 norm(vec4 p, float size, int mode, vec2 cell) {
    vec2 off=vec2(0.01,0);
    return normalize(vec3(
        map(p+off.xyyy, size, mode, cell)-map(p-off.xyyy, size, mode, cell),
        map(p+off.yxyy, size, mode, cell)-map(p-off.yxyy, size, mode, cell),
        map(p+off.yyxy, size, mode, cell)-map(p-off.yyxy, size, mode, cell)
    ));
}

float rnd(vec2 uv) {
    return fract(dot(sin(uv*vec2(172.412,735.124)+uv.yx*vec2(97.354,421.653)+vec2(94.321,37.365)),vec2(4.6872,7.9841))+0.71243);
}

vec3 GetCol(vec2 uv, float motion, float size, int mode, vec2 cell) {
    vec4 s=vec4(0,0,-4,motion);
    vec4 r=normalize(vec4(-uv*1.2, 1,0));
    float dd = 0.0;
    vec4 p = s;
    float at=0.0;
    float show=1.0;

    for(int i=0; i<MAXSTEPS; ++i) {
        float d = map(p, size, mode, cell);
        if(d<0.001) break;
        p+=r*d;
        dd+=d;
        if(dd>100.0) {
            show=0.0;
            break;
        }
        at += exp(-d)*0.8;
    }

    vec3 n=norm(p, size, mode, cell);
    vec3 l=normalize(vec3(-1));
    float lum=max(0.0, dot(l,n));
    vec3 col = vec3(0);

    if (mode == 0) {
        col += lum * vec3(2.0, 1.8, 1.5);
        col += lum * pow(max(0.0, dot(n, normalize(-r.xyz+l))), 12.0) * vec3(1.0,0.5,0.2);
    }
    else if (mode == 1) {
        col += lum * vec3(1.5, 2.0, 1.8);
        col += lum * pow(max(0.0, dot(n, normalize(-r.xyz+l))), 8.0) * vec3(0.2,1.0,0.8);
    }
    else if (mode == 2) {
        col += lum * vec3(1.8, 1.5, 2.0) * 1.2;
        col += lum * pow(max(0.0, dot(n, normalize(-r.xyz+l))), 15.0) * vec3(0.9,0.3,1.0);
    }
    else {
        col += lum * vec3(2.0, 1.8, 1.5) * 1.1;
        col += lum * pow(max(0.0, dot(n, normalize(-r.xyz+l))), 10.0) * vec3(1.0,0.2,0.5);
    }

    col += (n.y*0.5+0.5) * vec3(0.1,0.3,0.5);
    col *= show*2.0/dd;
    col += vec3(0.8,0.2,0.2)*0.02/exp(-at*0.3);

    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / v2Resolution.xy;
    uv -= 0.5;
    uv /= vec2(v2Resolution.y / v2Resolution.x, 1);

    // 2x2 grid
    vec2 grid_pos = floor(uv * 8.0 + 1.0);
    vec2 cell_uv = fract(uv * 8.0) - 0.5;
    uv = cell_uv;
    float section = grid_pos.x + grid_pos.y * 2.0;

    float str = 1.7;
    float off = rnd(uv);
    vec3 col = vec3(0.0);
    float size = 0.87+sin(time*0.2)*0.1;

    int mode = int(mod(section, 3.0));

    for(int i=0; i<SAMPLES_W; ++i) {
        float motion = (float(i)+off)/float(SAMPLES_W);
        motion = motion * 2.0 - 1.0;

        if (mode == 2) {
            motion = motion*motion*sign(motion);
        }

        motion *= str;
        col += GetCol(uv, motion, size, mode, grid_pos);
    }

    col *= size*4.0/float(SAMPLES_W);

    // grid separators
    vec2 sep = abs(fract(fragCoord.xy / v2Resolution.xy * 2.0) - 0.5);
    float separator = max(
        smoothstep(0.497, 0.5, sep.x),
        smoothstep(0.497, 0.5, sep.y)
    );
    col = mix(col, vec3(0.05), separator);

    fragColor = vec4(col, 1.0);
}
